@app.post("/photos", status_code=201)
async def upload_photo(photo: UploadFile = File(...), token: str = Form(...)):
    if not token:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Token is required")
    if not photo:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Photo is required")

    file_data = await photo.read()
    content_type = photo.content_type or "application/octet-stream"

    # Strip invisible metadata before storage
    try:
        sanitized_data = sanitize_png(file_data)
    except ValueError as e:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=f"Invalid image: {e}")

    photo_id = uuid.uuid4().hex

    try:
        with closing(sqlite3.connect(DB_NAME)) as conn:
            conn.execute(
                "INSERT INTO photos (photo_id, token, file_data, content_type) VALUES (?, ?, ?, ?)",
                (photo_id, token, sanitized_data, content_type),
            )
            conn.commit()
    except sqlite3.Error:
        raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail="Database error")

    return {"photo_id": photo_id, "token": token}

@app.get("/photos/{photo_id}")
def download_photo(photo_id: str, token: str = None):
    if not token:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Token is required")

    try:
        with closing(sqlite3.connect(DB_NAME)) as conn:
            conn.row_factory = sqlite3.Row
            cursor = conn.execute(
                "SELECT file_data, content_type, token FROM photos WHERE photo_id = ?",
                (photo_id,),
            )
            row = cursor.fetchone()
            if row is None:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Photo not found")

            # Strict per‑photo token check – no master key bypass
            if row["token"] != token:
                raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid token")

            # Sanitize again before serving (defence in depth)
            try:
                clean_data = sanitize_png(row["file_data"])
            except ValueError:
                raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail="Image processing error")

            return Response(content=clean_data, media_type=row["content_type"])
    except sqlite3.Error:
        raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail="Database error")
    except HTTPException:
        raise

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=5000)
